const revokeExpiredShare = `-- name: RevokeExpiredShare :one
UPDATE federation_shares
SET revoked_at          = NOW(),
    revoked_activity_id = $2,
    updated_at          = NOW()
WHERE id = $1
  AND revoked_at IS NULL
  AND expires_at IS NOT NULL
  AND expires_at <= NOW()
RETURNING id, grantor_user_ref, object_kind, object_id,
          peer_id, target_user_url, scope, expires_at, notes,
          granted_activity_id, granted_at, revoked_at,
          revoked_activity_id, created_at, updated_at, allow_original, allow_access_copies
`

type RevokeExpiredShareParams struct {
	ID                pgtype.UUID
	RevokedActivityID pgtype.UUID
}

// #1586: RevokeShare, but only while the row is STILL expired. The
// expiry retirement (the sweeper and the regrant path) reads a row as
// expired and closes it in a later statement; nothing locks the row in
// between. If its expiry was extended in that window the row is live
// again, and this UPDATE matches nothing (pgx.ErrNoRows), so the caller
// rolls back its aa:Unshare and leaves the live grant untouched. Same
// shape and RETURNING as RevokeShare.
func (q *Queries) RevokeExpiredShare(ctx context.Context, arg RevokeExpiredShareParams) (FederationShare, error) {
	row := q.db.QueryRow(ctx, revokeExpiredShare, arg.ID, arg.RevokedActivityID)
	var i FederationShare
	err := row.Scan(
		&i.ID,
		&i.GrantorUserRef,
		&i.ObjectKind,
		&i.ObjectID,
		&i.PeerID,
		&i.TargetUserUrl,
		&i.Scope,
		&i.ExpiresAt,
		&i.Notes,
		&i.GrantedActivityID,
		&i.GrantedAt,
		&i.RevokedAt,
		&i.RevokedActivityID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.AllowOriginal,
		&i.AllowAccessCopies,
	)
	return i, err
}

const revokeShare = `-- name: RevokeShare :one
UPDATE federation_shares
SET revoked_at          = NOW(),
    revoked_activity_id = $2,
    updated_at          = NOW()
WHERE id = $1 AND revoked_at IS NULL
RETURNING id, grantor_user_ref, object_kind, object_id,
          peer_id, target_user_url, scope, expires_at, notes,
          granted_activity_id, granted_at, revoked_at,
          revoked_activity_id, created_at, updated_at, allow_original, allow_access_copies
`

type RevokeShareParams struct {
	ID                pgtype.UUID
	RevokedActivityID pgtype.UUID
}

// Mark a share revoked + capture the aa:Unshare activity UUID.
// Idempotent: re-revoking a revoked row is a no-op (returns the
// existing revoked row unchanged via the WHERE filter).
func (q *Queries) RevokeShare(ctx context.Context, arg RevokeShareParams) (FederationShare, error) {
	row := q.db.QueryRow(ctx, revokeShare, arg.ID, arg.RevokedActivityID)
	var i FederationShare
	err := row.Scan(
		&i.ID,
		&i.GrantorUserRef,
		&i.ObjectKind,
		&i.ObjectID,
		&i.PeerID,
		&i.TargetUserUrl,
		&i.Scope,
		&i.ExpiresAt,
		&i.Notes,
		&i.GrantedActivityID,
		&i.GrantedAt,
		&i.RevokedAt,
		&i.RevokedActivityID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.AllowOriginal,
		&i.AllowAccessCopies,
	)
	return i, err
}
